mapper.delete:
DELETE FROM t_agent_memory
WHERE namespace_code=#{namespace} AND memory_code=#{code}
  AND (scope_type<>'AGENT' OR agent_code=#{agent})

mapper.select:
SELECT memory_code memoryCode,namespace_code namespaceCode,agent_code agentCode,scope_type scopeType,scope_code scopeCode,
  memory_level memoryLevel,content,tags_json tags,source_type sourceType,source_ref sourceRef,confidence,importance,
  expires_at expiresAt,status,created_time createdTime,updated_time updatedTime
FROM t_agent_memory
WHERE namespace_code=#{namespace}
AND status=#{status}
AND scope_type=#{scopeType}
AND scope_code=#{scopeCode}
ORDER BY updated_time DESC,id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT memory_code memoryCode,agent_code agentCode,scope_type scopeType,scope_code scopeCode,operation,
  old_status oldStatus,new_status newStatus,reason,operator_id operatorId,created_time createdTime
FROM t_agent_memory_governance_event
WHERE namespace_code=#{namespace}
ORDER BY created_time DESC,id DESC
LIMIT #{limit} OFFSET #{offset}
